        q("LP-01", "Digit Reverser & Sum of Digits", "Given a non-negative integer N, compute its reversed number and the sum of its digits.", "Loops", "While Loops & Digit Extraction", "Easy", "1234", "4321 10", "5080", "805 13", "0 <= N <= 10^15", "Single non-negative integer N.", "<reversed> <digit_sum>", "loops,digits,math", "O(log10 N)", "O(1)", "reverseAndSumDigits", "n: Long", "String", "fun reverseAndSumDigits(n: Long): String { var x = n; var rev = 0L; var sum = 0L; while (x > 0) { val d = x % 10; rev = rev * 10 + d; sum += d; x /= 10 }; return \"\$rev \$sum\" }"),
        q("LP-02", "Factorial & Trailing Zero Count", "Given N (0 <= N <= 20), compute N! (N factorial) and count how many trailing zeros it has.", "Loops", "Multiplicative Accumulation", "Easy", "5", "120 1", "10", "3628800 2", "0 <= N <= 20", "Single integer N.", "<factorial> <trailing_zeros>", "loops,factorial,math", "O(N)", "O(1)", "factorialStats", "n: Int", "String", "fun factorialStats(n: Int): String { var f = 1L; for (i in 2..n) f *= i; var tz = 0; var t = n; while (t >= 5) { tz += t / 5; t /= 5 }; return \"\$f \$tz\" }"),
