        q("LP-05", "Multiplication Table Summary", "Given integer N and limit K, output the first K multiples of N separated by spaces.", "Loops", "Step Iteration", "Easy", "7 5", "7 14 21 28 35", "3 4", "3 6 9 12", "1 <= N <= 10^5, 1 <= K <= 50", "Two integers N and K.", "Space-separated multiples.", "loops,multiples,iteration", "O(K)", "O(K)", "multiplesList", "n: Long, k: Int", "String", "fun multiplesList(n: Long, k: Int) = (1..k).joinToString(\" \") { (n * it).toString() }"),
        q("LP-06", "Power A^B by Repeated Multiplication", "Given integer base A and non-negative exponent B (0 <= B <= 18), compute A^B using a loop.", "Loops", "Iterative Exponentiation", "Easy", "2 10", "1024", "3 5", "243", "-10 <= A <= 10, 0 <= B <= 18", "Two integers A and B.", "Value of A^B.", "loops,power,math", "O(B)", "O(1)", "iterativePower", "a: Long, b: Int", "String", "fun iterativePower(a: Long, b: Int): String { var res = 1L; repeat(b) { res *= a }; return res.toString() }"),
        q("LP-07", "Palindrome Number Checker", "Given a non-negative integer N, determine if its base-10 representation reads the same forward and backward (YES or NO).", "Loops", "Number Reversal", "Easy", "12321", "YES", "1234", "NO", "0 <= N <= 10^15", "Single integer N.", "YES or NO", "loops,palindrome,digits", "O(log10 N)", "O(1)", "isNumericPalindrome", "n: Long", "String", "fun isNumericPalindrome(n: Long): String { var x = n; var r = 0L; while (x > 0) { r = r * 10 + x % 10; x /= 10 }; return if (r == n) \"YES\" else \"NO\" }"),
        q("LP-08", "Harmonic Series Partial Sum", "Given positive integer N, compute H_N = 1/1 + 1/2 + 1/3 + ... + 1/N rounded to 4 decimal places.", "Loops", "Floating-Point Summation", "Easy", "4", "2.0833", "1", "1.0000", "1 <= N <= 10^6", "Single integer N.", "Harmonic sum to 4 decimal places.", "loops,series,harmonic", "O(N)", "O(1)", "harmonicSum", "n: Int", "String", "fun harmonicSum(n: Int): String { var s = 0.0; for (i in 1..n) s += 1.0 / i; return String.format(java.util.Locale.US, \"%.4f\", s) }"),
        q("LP-09", "Product of Non-Zero Digits", "Given a positive integer N, multiply all of its non-zero digits together and return the product.", "Loops", "Conditional Digit Filtering", "Easy", "2054", "40", "1009", "9", "1 <= N <= 10^18", "Single integer N.", "Product of non-zero digits.", "loops,digits,product", "O(log10 N)", "O(1)", "nonZeroDigitProduct", "n: Long", "String", "fun nonZeroDigitProduct(n: Long): String { var x = n; var p = 1L; while (x > 0) { val d = x % 10; if (d != 0L) p *= d; x /= 10 }; return p.toString() }"),
        q("LP-10", "Count Multiples in Range [L, R]", "Given integers L, R, and K, count how many integers in [L, R] are divisible by K.", "Loops", "Range Iteration", "Easy", "10 25 5", "4", "1 10 3", "3", "1 <= L <= R <= 10^7, 1 <= K <= 10^7", "Three integers L, R, K.", "Count of multiples.", "loops,range,divisibility", "O(1)", "O(1)", "countMultiplesInRange", "l: Long, r: Long, k: Long", "String", "fun countMultiplesInRange(l: Long, r: Long, k: Long) = ((r / k) - ((l - 1) / k)).toString()"),

        // 10 Medium (LP-11 .. LP-20)
