        q("LP-12", "Armstrong / Narcissistic Number Checker", "Given a positive integer N with D digits, check if the sum of its digits each raised to the D-th power equals N (YES or NO).", "Loops", "Digit Power Sum", "Medium", "153", "YES", "9474", "YES", "1 <= N <= 10^9", "Single integer N.", "YES or NO", "loops,armstrong,digits", "O(log10 N)", "O(1)", "isArmstrong", "n: Long", "String", "fun isArmstrong(n: Long): String { val s = n.toString(); val d = s.length; var sum = 0L; for (ch in s) sum += Math.pow((ch - '0').toDouble(), d.toDouble()).toLong(); return if (sum == n) \"YES\" else \"NO\" }"),
        q("LP-13", "Decimal to Binary & Octal Converter", "Given non-negative integer N, convert it into its base-2 (binary) and base-8 (octal) string representations using division loops.", "Loops", "Base Conversion", "Medium", "13", "1101 15", "64", "1000000 100", "0 <= N <= 10^15", "Single integer N.", "<binary> <octal>", "loops,radix,binary", "O(log N)", "O(log N)", "toBinaryAndOctal", "n: Long", "String", "fun toBinaryAndOctal(n: Long) = \"\${java.lang.Long.toBinaryString(n)} \${java.lang.Long.toOctalString(n)}\""),
        q("LP-14", "Strong / Krishnamurthy Number Validator", "Given positive integer N, check if the sum of factorials of its digits equals N (e.g., 145 = 1! + 4! + 5! -> YES).", "Loops", "Digit Factorial Lookup", "Medium", "145", "YES", "123", "NO", "1 <= N <= 10^9", "Single integer N.", "YES or NO", "loops,factorial,digits", "O(log10 N)", "O(1)", "isStrongNumber", "n: Long", "String", "fun isStrongNumber(n: Long): String { val f = intArrayOf(1,1,2,6,24,120,720,5040,40320,362880); var x = n; var s = 0L; while (x > 0) { s += f[(x % 10).toInt()]; x /= 10 }; return if (s == n) \"YES\" else \"NO\" }"),
        q("LP-15", "Pascal Triangle N-th Row Generator", "Given 0-indexed row number N (0 <= N <= 30), generate all N+1 binomial coefficients C(N, 0) .. C(N, N) separated by spaces.", "Loops", "Multiplicative Binomial Loop", "Medium", "4", "1 4 6 4 1", "5", "1 5 10 10 5 1", "0 <= N <= 30", "Single integer N.", "Space-separated row values.", "loops,combinatorics,pascal", "O(N)", "O(N)", "pascalRow", "n: Int", "String", "fun pascalRow(n: Int): String { val res = mutableListOf(1L); var cur = 1L; for (k in 1..n) { cur = cur * (n - k + 1) / k; res.add(cur) }; return res.joinToString(\" \") }"),
        q("LP-16", "Automorphic Number Checker", "Given positive integer N, check if N^2 ends with the exact digits of N (e.g., 25^2 = 625 -> YES; 76^2 = 5776 -> YES).", "Loops", "Suffix Digit Matching", "Medium", "25", "YES", "14", "NO", "1 <= N <= 10^9", "Single integer N.", "YES or NO", "loops,math,digits", "O(log10 N)", "O(1)", "isAutomorphic", "n: Long", "String", "fun isAutomorphic(n: Long) = if ((n * n).toString().endsWith(n.toString())) \"YES\" else \"NO\""),
        q("LP-17", "Single-Digit Digital Root Step Counter", "Given non-negative integer N, repeatedly sum its digits until a single digit remains. Output the final digital root and how many steps it took.", "Loops", "Nested Reduction Loops", "Medium", "9875", "2 2", "7", "7 0", "0 <= N <= 10^18", "Single integer N.", "<digital_root> <steps>", "loops,digits,reduction", "O(log N)", "O(1)", "digitalRootSteps", "n: Long", "String", "fun digitalRootSteps(n: Long): String { var x = n; var steps = 0; while (x >= 10) { var s = 0L; while (x > 0) { s += x % 10; x /= 10 }; x = s; steps++ }; return \"\$x \$steps\" }"),
        q("LP-18", "Happy Number Cycle Detector", "Given positive integer N, repeatedly replace N with the sum of squares of its digits. Output HAPPY if it reaches 1, or CYCLE if it enters a loop.", "Loops", "Floyd Cycle Detection", "Medium", "19", "HAPPY", "20", "CYCLE", "1 <= N <= 10^9", "Single integer N.", "HAPPY or CYCLE", "loops,cycle,digits", "O(log N)", "O(1)", "isHappyNumber", "n: Long", "String", "fun isHappyNumber(n: Long): String { fun nxt(v: Long): Long { var x = v; var s = 0L; while (x > 0) { val d = x % 10; s += d * d; x /= 10 }; return s }; var slow = n; var fast = nxt(n); while (fast != 1L && slow != fast) { slow = nxt(slow); fast = nxt(nxt(fast)) }; return if (fast == 1L) \"HAPPY\" else \"CYCLE\" }"),
        q("LP-19", "Alternating Series Sum", "Given N, compute 1^2 - 2^2 + 3^2 - 4^2 + ... + (-1)^(N-1) * N^2.", "Loops", "Alternating Sign Iteration", "Medium", "4", "-10", "5", "15", "1 <= N <= 10^6", "Single integer N.", "Alternating square sum.", "loops,series,math", "O(N)", "O(1)", "alternatingSquareSum", "n: Long", "String", "fun alternatingSquareSum(n: Long): String { var s = 0L; for (i in 1..n) s += if (i % 2L == 1L) i * i else -(i * i); return s.toString() }"),
        q("LP-20", "Tribonacci N-th Term", "Given T_0 = 0, T_1 = 1, T_2 = 1, and T_n = T_{n-1} + T_{n-2} + T_{n-3}, compute T_N for 0 <= N <= 37.", "Loops", "Three-State Rolling Variables", "Medium", "4", "4", "25", "1389537", "0 <= N <= 37", "Single integer N.", "N-th Tribonacci number.", "loops,tribonacci,dp", "O(N)", "O(1)", "tribonacci", "n: Int", "String", "fun tribonacci(n: Int): String { if (n == 0) return \"0\"; if (n <= 2) return \"1\"; var a = 0L; var b = 1L; var c = 1L; for (i in 3..n) { val d = a + b + c; a = b; b = c; c = d }; return c.toString() }"),

        // 10 Hard (LP-21 .. LP-30)
        q("LP-21", "Collatz Conjecture Peak & Stopping Time", "Given starting integer N, apply 3N+1 if odd and N/2 if even until N reaches 1. Output the total steps and the maximum value reached.", "Loops", "Unbounded Convergence Loops", "Hard", "6", "Steps=8 Peak=16", "27", "Steps=111 Peak=9232", "1 <= N <= 10^6", "Single integer N.", "Steps=<count> Peak=<max_val>", "loops,collatz,simulation", "O(steps)", "O(1)", "analyzeCollatz", "n: Long", "String", "fun analyzeCollatz(n: Long): String { var cur = n; var steps = 0; var peak = n; while (cur > 1L) { cur = if (cur % 2L == 0L) cur / 2L else 3L * cur + 1L; if (cur > peak) peak = cur; steps++ }; return \"Steps=\$steps Peak=\$peak\" }"),
        q("LP-22", "Integer Square Root & Cube Root by Binary Search Loop", "Given non-negative 64-bit integer N (0 <= N <= 10^18), find floor(sqrt(N)) and floor(cbrt(N)) using integer binary search loops.", "Loops", "Monotonic Search Loop", "Hard", "27", "5 3", "100", "10 4", "0 <= N <= 10^18", "Single integer N.", "<floor_sqrt> <floor_cbrt>", "loops,binarysearch,roots", "O(log N)", "O(1)", "intRoots", "n: Long", "String", "fun intRoots(n: Long): String { val sq = kotlin.math.sqrt(n.toDouble()).toLong(); val cb = Math.cbrt(n.toDouble()).toLong(); return \"\$sq \$cb\" }"),
        q("LP-23", "Josephus Survivor Circle", "Given N people numbered 1..N in a circle where every K-th person is eliminated, compute the 1-indexed survivor position using an iterative loop.", "Loops", "Modular Recurrence Loop", "Hard", "7 3", "4", "5 2", "3", "1 <= N <= 10^6, 1 <= K <= 10^6", "Two integers N and K.", "1-based index of survivor.", "loops,josephus,math", "O(N)", "O(1)", "josephusSurvivor", "n: Int, k: Int", "String", "fun josephusSurvivor(n: Int, k: Int): String { var res = 0; for (i in 2..n) res = (res + k) % i; return (res + 1).toString() }"),
        q("LP-24", "Kaprekar Constant 6174 Convergence", "Given a 4-digit number N (not all digits identical), repeatedly sort digits descending minus ascending (padded to 4 digits) until reaching 6174. Output step count.", "Loops", "Fixed-Point Iteration", "Hard", "3524", "3", "2111", "5", "1000 <= N <= 9999, not a repdigit", "4-digit integer N.", "Number of routine steps to reach 6174.", "loops,kaprekar,simulation", "O(1)", "O(1)", "kaprekarSteps", "n: Int", "String", "fun kaprekarSteps(n: Int): String { var cur = n; var steps = 0; while (cur != 6174) { val s = String.format(java.util.Locale.US, \"%04d\", cur).toCharArray().sorted(); val asc = s.joinToString(\"\").toInt(); val desc = s.reversed().joinToString(\"\").toInt(); cur = desc - asc; steps++ }; return steps.toString() }"),
        q("LP-25", "Look-and-Say Sequence N-th Term", "Starting from \"1\", generate the N-th term of the Look-and-Say sequence (1 -> 11 -> 21 -> 1211 -> 111221).", "Loops", "Run-Length Generation Loop", "Hard", "4", "1211", "5", "111221", "1 <= N <= 20", "Single integer N.", "N-th Look-and-Say string.", "loops,simulation,rle", "O(2^N)", "O(2^N)", "lookAndSay", "n: Int", "String", "fun lookAndSay(n: Int): String { var cur = \"1\"; repeat(n - 1) { val sb = StringBuilder(); var i = 0; while (i < cur.length) { var j = i; while (j < cur.length && cur[j] == cur[i]) j++; sb.append(j - i).append(cur[i]); i = j }; cur = sb.toString() }; return cur }"),
        q("LP-26", "Maximum Subarray Kadane Loop", "Given N integers, find the maximum possible sum of a non-empty contiguous subarray in a single pass.", "Loops", "Running Optimum Loop", "Hard", "-2 1 -3 4 -1 2 1 -5 4", "6", "5 -2 3 4", "10", "1 <= N <= 10^5", "Space-separated integers.", "Maximum contiguous sum.", "loops,kadane,dp", "O(N)", "O(1)", "kadaneLoop", "nums: List<Long>", "String", "fun kadaneLoop(nums: List<Long>): String { var cur = nums[0]; var best = nums[0]; for (i in 1 until nums.size) { cur = maxOf(nums[i], cur + nums[i]); best = maxOf(best, cur) }; return best.toString() }"),
        q("LP-27", "Roman Numeral Encoder", "Given an integer N (1 <= N <= 3999), convert it into its standard Roman numeral string using a greedy value-symbol loop.", "Loops", "Greedy Subtraction Loop", "Hard", "1994", "MCMXCIV", "58", "LVIII", "1 <= N <= 3999", "Single integer N.", "Roman numeral string.", "loops,roman,greedy", "O(1)", "O(1)", "intToRoman", "n: Int", "String", "fun intToRoman(n: Int): String { val vals = intArrayOf(1000,900,500,400,100,90,50,40,10,9,5,4,1); val syms = arrayOf(\"M\",\"CM\",\"D\",\"CD\",\"C\",\"XC\",\"L\",\"XL\",\"X\",\"IX\",\"V\",\"IV\",\"I\"); var x = n; val sb = StringBuilder(); for (i in vals.indices) while (x >= vals[i]) { sb.append(syms[i]); x -= vals[i] }; return sb.toString() }"),
        q("LP-28", "Count Numbers With Unique Digits in [1, N]", "Given N (1 <= N <= 10^5), count how many integers in 1..N have no repeated base-10 digits.", "Loops", "Bitmask Digit Tracking", "Hard", "20", "19", "100", "90", "1 <= N <= 10^5", "Single integer N.", "Count of numbers with distinct digits.", "loops,bitmask,digits", "O(N log10 N)", "O(1)", "countUniqueDigitNumbers", "n: Int", "String", "fun countUniqueDigitNumbers(n: Int): String { var cnt = 0; for (i in 1..n) { var x = i; var mask = 0; var ok = true; while (x > 0) { val b = 1 shl (x % 10); if ((mask and b) != 0) { ok = false; break }; mask = mask or b; x /= 10 }; if (ok) cnt++ }; return cnt.toString() }"),
        q("LP-29", "Balanced Ternary Converter", "Given a positive integer N, convert it into balanced ternary using digits '1' (+1), '0' (0), and 'T' (-1).", "Loops", "Carry-Adjusted Radix Loop", "Hard", "5", "1TT", "11", "101", "1 <= N <= 10^12", "Single integer N.", "Balanced ternary string.", "loops,ternary,math", "O(log3 N)", "O(log3 N)", "toBalancedTernary", "n: Long", "String", "fun toBalancedTernary(n: Long): String { var x = n; val sb = StringBuilder(); while (x > 0) { when (val r = (x % 3).toInt()) { 0 -> { sb.append('0'); x /= 3 }; 1 -> { sb.append('1'); x /= 3 }; 2 -> { sb.append('T'); x = (x + 1) / 3 } } }; return sb.reverse().toString() }"),
        q("LP-30", "Prime Factorization Exponent String", "Given integer N >= 2, extract all prime factors and their exponents in ascending order formatted as p1^e1 * p2^e2.", "Loops", "Trial Division Loop", "Hard", "360", "2^3 * 3^2 * 5^1", "100", "2^2 * 5^2", "2 <= N <= 10^12", "Single integer N.", "Formatted prime power product.", "loops,primes,factorization", "O(sqrt(N))", "O(log N)", "primeFactorString", "n: Long", "String", "fun primeFactorString(n: Long): String { var x = n; val parts = mutableListOf<String>(); var d = 2L; while (d * d <= x) { if (x % d == 0L) { var c = 0; while (x % d == 0L) { c++; x /= d }; parts.add(\"\$d^\$c\") }; d++ }; if (x > 1) parts.add(\"\$x^1\"); return parts.joinToString(\" * \") }")
    )

