        // 10 Easy (ST-01 .. ST-10)
        q("ST-01", "Alphanumeric Palindrome Detector", "Given a string S, ignore all non-alphanumeric characters and case differences, then determine if it is a palindrome (TRUE or FALSE).", "Strings", "Two-Pointer String Traversal", "Easy", "A man, a plan, a canal: Panama", "TRUE", "CodeQuest AI", "FALSE", "1 <= |S| <= 2 * 10^5", "A single line string S.", "TRUE or FALSE", "strings,two-pointers,palindrome", "O(N)", "O(N)", "isCleanPalindrome", "s: String", "String", "fun isCleanPalindrome(s: String): String { val c = s.filter { it.isLetterOrDigit() }.lowercase(); return if (c == c.reversed()) \"TRUE\" else \"FALSE\" }"),
