        q("ST-03", "Reverse Words in Sentence", "Given a sentence S of space-separated words, reverse the order of the words while keeping each word's characters intact.", "Strings", "Token Splitting & Joining", "Easy", "CodeQuest makes coding fun", "fun coding makes CodeQuest", "hello world", "world hello", "1 <= |S| <= 10^5", "Sentence S.", "Words in reversed order.", "strings,words,reverse", "O(N)", "O(N)", "reverseWordsOrder", "s: String", "String", "fun reverseWordsOrder(s: String) = s.trim().split(Regex(\"\\\\s+\")).reversed().joinToString(\" \")"),
        q("ST-04", "Toggle Case of String", "Given a string S, convert all uppercase letters to lowercase and all lowercase letters to uppercase.", "Strings", "Case Transformation", "Easy", "CodeQuest_2026", "cODEqUEST_2026", "Kotlin!", "kOTLIN!", "1 <= |S| <= 10^5", "String S.", "Case-toggled string.", "strings,case,ascii", "O(N)", "O(N)", "toggleCase", "s: String", "String", "fun toggleCase(s: String) = s.map { if (it.isUpperCase()) it.lowercaseChar() else if (it.isLowerCase()) it.uppercaseChar() else it }.joinToString(\"\")"),
        q("ST-05", "First Non-Repeating Character", "Given a string S, return the first character that appears exactly once, or '_' if every character repeats.", "Strings", "Frequency Map", "Easy", "leetcode", "l", "aabb", "_", "1 <= |S| <= 10^5", "String S.", "First unique character or '_'.", "strings,frequency,hashing", "O(N)", "O(1)", "firstUniqueChar", "s: String", "String", "fun firstUniqueChar(s: String): String { val cnt = s.groupingBy { it }.eachCount(); return (s.firstOrNull { cnt[it] == 1 } ?: '_').toString() }"),
        q("ST-06", "Anagram Pair Checker", "Given two strings S and T, output YES if T is a valid anagram of S (case-insensitive, ignoring spaces), else NO.", "Strings", "Character Histograms", "Easy", "Listen Silent", "YES", "Hello World", "NO", "1 <= |S|, |T| <= 10^5", "Two strings S and T.", "YES or NO", "strings,anagram,sorting", "O(N log N)", "O(N)", "areAnagrams", "s: String, t: String", "String", "fun areAnagrams(s: String, t: String): String { val a = s.filter { !it.isWhitespace() }.lowercase().toCharArray().sorted(); val b = t.filter { !it.isWhitespace() }.lowercase().toCharArray().sorted(); return if (a == b) \"YES\" else \"NO\" }"),
        q("ST-07", "Pangram Sentence Validator", "Given a sentence S, output YES if it contains every letter of the English alphabet ('a'..'z') at least once, else NO.", "Strings", "Alphabet Set Coverage", "Easy", "The quick brown fox jumps over the lazy dog", "YES", "Pack my box with five dozen jugs", "NO", "1 <= |S| <= 10^5", "Single line sentence S.", "YES or NO", "strings,pangram,set", "O(N)", "O(1)", "isPangram", "s: String", "String", "fun isPangram(s: String) = if (s.lowercase().filter { it in 'a'..'z' }.toSet().size == 26) \"YES\" else \"NO\""),
        q("ST-08", "Remove Consecutive Duplicate Characters", "Given a string S, collapse any run of identical adjacent characters into a single character (e.g., 'aaabbcddd' -> 'abcd').", "Strings", "Linear Deduplication", "Easy", "aaabbcddd", "abcd", "mississippi", "misisipi", "1 <= |S| <= 10^5", "String S.", "Collapsed string.", "strings,deduplication,iteration", "O(N)", "O(N)", "collapseDuplicates", "s: String", "String", "fun collapseDuplicates(s: String): String { val sb = StringBuilder(); for (c in s) if (sb.isEmpty() || sb.last() != c) sb.append(c); return sb.toString() }"),
        q("ST-09", "CamelCase to snake_case Converter", "Given a camelCase or PascalCase identifier S, convert it into lowercase snake_case.", "Strings", "Identifier Formatting", "Easy", "userProfileSettings", "user_profile_settings", "CodeQuestAI", "code_quest_a_i", "1 <= |S| <= 1000", "Identifier string S.", "snake_case string.", "strings,formatting,parsing", "O(N)", "O(N)", "camelToSnake", "s: String", "String", "fun camelToSnake(s: String): String { val sb = StringBuilder(); for ((i, c) in s.withIndex()) { if (c.isUpperCase() && i > 0) sb.append('_'); sb.append(c.lowercaseChar()) }; return sb.toString() }"),
        q("ST-10", "Longest Word in Sentence", "Given a sentence S, find and output the longest space-separated word (if tied, return the first one) and its length.", "Strings", "Token Scanning", "Easy", "Practice algorithms every single day", "algorithms 10", "AI is fast", "fast 4", "1 <= |S| <= 10^5", "Sentence S.", "<word> <length>", "strings,tokens,max", "O(N)", "O(N)", "longestWord", "s: String", "String", "fun longestWord(s: String): String { val w = s.trim().split(Regex(\"\\\\s+\")).maxByOrNull { it.length } ?: \"\"; return \"\$w \${w.length}\" }"),

        // 10 Medium (ST-11 .. ST-20)
        q("ST-11", "Run-Length String Compressor", "Compress string S by replacing consecutive identical characters with the character followed by its count. Return the shorter of compressed vs original.", "Strings", "Frequency & Compression", "Medium", "aaabbcdddd", "a3b2c1d4", "abc", "abc", "1 <= |S| <= 10^5", "Single string S.", "Compressed string or original if not shorter.", "strings,compression,rle", "O(N)", "O(N)", "compressRunLength", "s: String", "String", "fun compressRunLength(s: String): String { if (s.isEmpty()) return s; val sb = StringBuilder(); var count = 1; for (i in 1..s.length) { if (i < s.length && s[i] == s[i - 1]) count++ else { sb.append(s[i - 1]).append(count); count = 1 } }; val res = sb.toString(); return if (res.length < s.length) res else s }"),
        q("ST-12", "Caesar Cipher Encoder & Rotation", "Given string S and integer shift K, shift all English letters forward by K positions (wrapping Z->A and z->a) while preserving case and punctuation.", "Strings", "Modular Alphabet Arithmetic", "Medium", "AttackAtDawn! 3", "DwwdfnDwGdzq!", "xyz 2", "zab", "1 <= |S| <= 10^5, 0 <= K <= 10^9", "String S and shift K.", "Ciphertext string.", "strings,cipher,modulo", "O(N)", "O(N)", "caesarCipher", "s: String, k: Int", "String", "fun caesarCipher(s: String, k: Int): String { val sh = ((k % 26) + 26) % 26; return s.map { when (it) { in 'a'..'z' -> 'a' + (it - 'a' + sh) % 26; in 'A'..'Z' -> 'A' + (it - 'A' + sh) % 26; else -> it } }.joinToString(\"\") }"),
        q("ST-13", "Longest Common Prefix of Words", "Given space-separated words, find their longest common prefix string (or 'NONE' if empty).", "Strings", "Prefix Matching", "Medium", "flower flow flight", "fl", "dog racecar car", "NONE", "1 <= words <= 1000", "Space-separated words.", "Longest common prefix or NONE.", "strings,prefix,scanning", "O(N * M)", "O(1)", "longestCommonPrefix", "words: List<String>", "String", "fun longestCommonPrefix(words: List<String>): String { if (words.isEmpty()) return \"NONE\"; var p = words[0]; for (w in words) { while (!w.startsWith(p)) { p = p.dropLast(1); if (p.isEmpty()) return \"NONE\" } }; return p }"),
        q("ST-14", "Isomorphic Strings Validator", "Given two strings S and T of equal length, determine if characters in S can be replaced 1-to-1 to get T (YES or NO).", "Strings", "Bijective Character Mapping", "Medium", "egg add", "YES", "foo bar", "NO", "1 <= |S| == |T| <= 10^5", "Two strings S and T.", "YES or NO", "strings,hashing,bijection", "O(N)", "O(1)", "areIsomorphic", "s: String, t: String", "String", "fun areIsomorphic(s: String, t: String): String { if (s.length != t.length) return \"NO\"; val m1 = IntArray(256); val m2 = IntArray(256); for (i in s.indices) { if (m1[s[i].code] != m2[t[i].code]) return \"NO\"; m1[s[i].code] = i + 1; m2[t[i].code] = i + 1 }; return \"YES\" }"),
        q("ST-15", "Balanced Bracket Expression Validator", "Given a string S containing '()', '[]', and '{}', output VALID if all brackets are properly nested and closed, else INVALID.", "Strings", "Stack Parsing", "Medium", "{[()()]}", "VALID", "([)]", "INVALID", "1 <= |S| <= 10^5", "Bracket string S.", "VALID or INVALID", "strings,stack,brackets", "O(N)", "O(N)", "isValidBrackets", "s: String", "String", "fun isValidBrackets(s: String): String { val st = ArrayDeque<Char>(); for (c in s) when (c) { '(', '[', '{' -> st.addLast(c); ')' -> if (st.removeLastOrNull() != '(') return \"INVALID\"; ']' -> if (st.removeLastOrNull() != '[') return \"INVALID\"; '}' -> if (st.removeLastOrNull() != '{') return \"INVALID\" }; return if (st.isEmpty()) \"VALID\" else \"INVALID\" }"),
        q("ST-16", "String Rotation Checker", "Given two strings S and T, output YES if T is a cyclic rotation of S (e.g., 'waterbottle' and 'erbottlewat'), else NO.", "Strings", "Concatenation Substring Trick", "Medium", "waterbottle erbottlewat", "YES", "hello world", "NO", "1 <= |S|, |T| <= 10^5", "Two strings S and T.", "YES or NO", "strings,rotation,substring", "O(N)", "O(N)", "isStringRotation", "s: String, t: String", "String", "fun isStringRotation(s: String, t: String) = if (s.length == t.length && (s + s).contains(t)) \"YES\" else \"NO\""),
        q("ST-17", "Longest Substring Without Repeating Characters", "Given a string S, find the length of the longest contiguous substring that contains no duplicate characters.", "Strings", "Sliding Window & Last Seen Index", "Medium", "abcabcbb", "3", "pwwkew", "3", "0 <= |S| <= 10^5", "String S.", "Maximum unique-character window length.", "strings,sliding-window,hashing", "O(N)", "O(1)", "longestUniqueSubstring", "s: String", "String", "fun longestUniqueSubstring(s: String): String { val last = IntArray(256) { -1 }; var l = 0; var best = 0; for (r in s.indices) { l = maxOf(l, last[s[r].code] + 1); best = maxOf(best, r - l + 1); last[s[r].code] = r }; return best.toString() }"),
        q("ST-18", "Roman Numeral to Integer Parser", "Given a valid Roman numeral string S (I, V, X, L, C, D, M), convert it into its decimal integer value.", "Strings", "Lookahead Subtractive Parsing", "Medium", "MCMXCIV", "1994", "LVIII", "58", "1 <= |S| <= 15", "Roman numeral string S.", "Integer value.", "strings,roman,parsing", "O(N)", "O(1)", "romanToInt", "s: String", "String", "fun romanToInt(s: String): String { val m = mapOf('I' to 1,'V' to 5,'X' to 10,'L' to 50,'C' to 100,'D' to 500,'M' to 1000); var ans = 0; for (i in s.indices) { val v = m[s[i]] ?: 0; val nxt = if (i + 1 < s.length) (m[s[i+1]] ?: 0) else 0; if (v < nxt) ans -= v else ans += v }; return ans.toString() }"),
        q("ST-19", "Expand Encoded Repeat String", "Given an encoded string like '3[a2[c]]', expand it into its decoded string 'accaccacc'.", "Strings", "Nested Stack Decoding", "Medium", "3[a2[c]]", "accaccacc", "2[abc]3[cd]ef", "abcabccdcdcdef", "1 <= |S| <= 1000", "Encoded string S.", "Expanded string.", "strings,stack,parsing", "O(|output|)", "O(N)", "decodeRepeatString", "s: String", "String", "fun decodeRepeatString(s: String): String { val counts = ArrayDeque<Int>(); val strs = ArrayDeque<StringBuilder>(); var cur = StringBuilder(); var k = 0; for (c in s) when { c.isDigit() -> k = k * 10 + (c - '0'); c == '[' -> { counts.addLast(k); strs.addLast(cur); cur = StringBuilder(); k = 0 }; c == ']' -> { val rep = counts.removeLast(); val prev = strs.removeLast(); repeat(rep) { prev.append(cur) }; cur = prev }; else -> cur.append(c) }; return cur.toString() }"),
        q("ST-20", "One-Edit Distance Validator", "Given two strings S and T, output YES if they are at most 1 edit (insert, delete, or replace) apart, else NO.", "Strings", "Two-Pointer Edit Check", "Medium", "pale ple", "YES", "pale bake", "NO", "0 <= |S|, |T| <= 10^5", "Two strings S and T.", "YES or NO", "strings,two-pointers,edits", "O(N)", "O(1)", "isOneEditApart", "s: String, t: String", "String", "fun isOneEditApart(s: String, t: String): String { if (kotlin.math.abs(s.length - t.length) > 1) return \"NO\"; var i = 0; var j = 0; var edits = 0; while (i < s.length && j < t.length) { if (s[i] == t[j]) { i++; j++ } else { edits++; if (edits > 1) return \"NO\"; if (s.length > t.length) i++ else if (s.length < t.length) j++ else { i++; j++ } } }; return \"YES\" }"),

        // 10 Hard (ST-21 .. ST-30)
        q("ST-21", "Minimum Window Substring Coverage", "Given source string S and target string T, find the shortest contiguous substring of S that contains all characters of T (with multiplicity). Output 'NONE' if impossible.", "Strings", "Sliding Window & Frequency Map", "Hard", "ADOBECODEBANC ABC", "BANC", "a aa", "NONE", "1 <= |S|, |T| <= 10^5", "Two space-separated strings S and T.", "Shortest valid substring or NONE.", "strings,sliding-window,hashing", "O(|S| + |T|)", "O(1)", "minWindowSubstring", "s: String, t: String", "String", "fun minWindowSubstring(s: String, t: String): String { val need = IntArray(128); for (c in t) need[c.code]++; var missing = t.length; var l = 0; var bestStart = 0; var bestLen = Int.MAX_VALUE; for (r in s.indices) { if (need[s[r].code]-- > 0) missing--; while (missing == 0) { if (r - l + 1 < bestLen) { bestLen = r - l + 1; bestStart = l }; if (++need[s[l++].code] > 0) missing++ } }; return if (bestLen == Int.MAX_VALUE) \"NONE\" else s.substring(bestStart, bestStart + bestLen) }"),
        q("ST-22", "KMP Pattern Occurrence Finder", "Given text S and pattern P, find all 0-based starting indices where P occurs in S using the Knuth-Morris-Pratt (KMP) prefix function.", "Strings", "KMP Prefix Automaton", "Hard", "ababcababa aba", "0 5 7", "aaaaa aa", "0 1 2 3", "1 <= |P| <= |S| <= 10^5", "Text S and pattern P.", "Space-separated indices or NONE.", "strings,kmp,pattern-matching", "O(|S| + |P|)", "O(|P|)", "kmpSearch", "s: String, p: String", "String", "fun kmpSearch(s: String, p: String): String { val comb = \"\$p#\${s}\"; val pi = IntArray(comb.length); val res = mutableListOf<Int>(); for (i in 1 until comb.length) { var j = pi[i - 1]; while (j > 0 && comb[i] != comb[j]) j = pi[j - 1]; if (comb[i] == comb[j]) j++; pi[i] = j; if (j == p.length) res.add(i - 2 * p.length) }; return if (res.isEmpty()) \"NONE\" else res.joinToString(\" \") }"),
        q("ST-23", "Longest Palindromic Substring", "Given a string S, find the longest contiguous substring of S that is a palindrome (if tied, return the earliest).", "Strings", "Center Expansion / Manacher", "Hard", "babad", "bab", "cbbd", "bb", "1 <= |S| <= 5000", "String S.", "Longest palindromic substring.", "strings,palindrome,expansion", "O(N^2)", "O(1)", "longestPalindromeSub", "s: String", "String", "fun longestPalindromeSub(s: String): String { var start = 0; var maxLen = 1; fun exp(l0: Int, r0: Int) { var l = l0; var r = r0; while (l >= 0 && r < s.length && s[l] == s[r]) { if (r - l + 1 > maxLen) { start = l; maxLen = r - l + 1 }; l--; r++ } }; for (i in s.indices) { exp(i, i); exp(i, i + 1) }; return s.substring(start, start + maxLen) }"),
        q("ST-24", "Levenshtein Edit Distance", "Given two strings S and T, compute the minimum number of single-character insertions, deletions, or substitutions required to transform S into T.", "Strings", "2D Dynamic Programming", "Hard", "horse ros", "3", "intention execution", "5", "0 <= |S|, |T| <= 1000", "Two strings S and T.", "Minimum edit distance.", "strings,dp,edit-distance", "O(|S| * |T|)", "O(|T|)", "editDistance", "s: String, t: String", "String", "fun editDistance(s: String, t: String): String { var dp = IntArray(t.length + 1) { it }; for (i in 1..s.length) { val nxt = IntArray(t.length + 1); nxt[0] = i; for (j in 1..t.length) nxt[j] = if (s[i-1] == t[j-1]) dp[j-1] else 1 + minOf(dp[j-1], dp[j], nxt[j-1]); dp = nxt }; return dp[t.length].toString() }"),
        q("ST-25", "Longest Common Subsequence Length", "Given two strings S and T, compute the length of their longest common subsequence (not necessarily contiguous).", "Strings", "Subsequence DP", "Hard", "abcde ace", "3", "abc def", "0", "1 <= |S|, |T| <= 1000", "Two strings S and T.", "LCS length.", "strings,dp,lcs", "O(|S| * |T|)", "O(|T|)", "lcsLength", "s: String, t: String", "String", "fun lcsLength(s: String, t: String): String { var dp = IntArray(t.length + 1); for (c in s) { val nxt = IntArray(t.length + 1); for (j in 1..t.length) nxt[j] = if (c == t[j-1]) dp[j-1] + 1 else maxOf(dp[j], nxt[j-1]); dp = nxt }; return dp[t.length].toString() }"),
        q("ST-26", "Z-Algorithm Prefix Match Array Sum", "Given a string S, compute its Z-array (where Z[i] is the length of the longest common prefix between S and the suffix of S starting at i, with Z[0]=0) and output the sum of all Z[i].", "Strings", "Z-Box Linear String Matching", "Hard", "aabcaabxaaaz", "12", "aaaaa", "10", "1 <= |S| <= 10^5", "Single string S.", "Sum of Z-array values.", "strings,z-algorithm,prefix", "O(N)", "O(N)", "zArraySum", "s: String", "String", "fun zArraySum(s: String): String { val n = s.length; val z = IntArray(n); var l = 0; var r = 0; for (i in 1 until n) { if (i <= r) z[i] = minOf(r - i + 1, z[i - l]); while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++; if (i + z[i] - 1 > r) { l = i; r = i + z[i] - 1 } }; return z.sum().toString() }"),
        q("ST-27", "Smallest Lexicographical Subsequence of Distinct Chars", "Given a lowercase string S, return the lexicographically smallest subsequence of S that contains every distinct character of S exactly once.", "Strings", "Monotonic Stack & Last Occurrence", "Hard", "cbacdcbc", "acdb", "bcabc", "abc", "1 <= |S| <= 10^5", "String S.", "Lexicographically smallest unique subsequence.", "strings,monotonic-stack,greedy", "O(N)", "O(1)", "removeDuplicateLetters", "s: String", "String", "fun removeDuplicateLetters(s: String): String { val last = IntArray(26); for (i in s.indices) last[s[i] - 'a'] = i; val seen = BooleanArray(26); val st = StringBuilder(); for (i in s.indices) { val c = s[i]; if (seen[c - 'a']) continue; while (st.isNotEmpty() && st.last() > c && last[st.last() - 'a'] > i) { seen[st.last() - 'a'] = false; st.deleteCharAt(st.lastIndex) }; st.append(c); seen[c - 'a'] = true }; return st.toString() }"),
        q("ST-28", "Rabin-Karp Distinct Substrings of Length K", "Given string S and length K, count how many distinct substrings of length K exist in S.", "Strings", "Rolling Hash / Sliding Set", "Hard", "ababa 3", "2", "aaaaa 2", "1", "1 <= K <= |S| <= 10^5", "String S and integer K.", "Count of distinct length-K substrings.", "strings,hashing,substrings", "O(N)", "O(N)", "distinctSubstringsOfK", "s: String, k: Int", "String", "fun distinctSubstringsOfK(s: String, k: Int): String { if (k > s.length) return \"0\"; val set = HashSet<String>(); for (i in 0..s.length - k) set.add(s.substring(i, i + k)); return set.size.toString() }"),
        q("ST-29", "Wildcard Pattern Matcher", "Given string S and pattern P supporting '?' (any single char) and '*' (any sequence of chars), output MATCH or NO_MATCH.", "Strings", "Two-Pointer Backtracking / DP", "Hard", "adceb *a*b", "MATCH", "acdcb a*c?b", "NO_MATCH", "0 <= |S|, |P| <= 2000", "String S and pattern P.", "MATCH or NO_MATCH", "strings,wildcard,dp", "O(|S| * |P|)", "O(1)", "wildcardMatch", "s: String, p: String", "String", "fun wildcardMatch(s: String, p: String): String { var i = 0; var j = 0; var star = -1; var match = 0; while (i < s.length) { if (j < p.length && (p[j] == '?' || p[j] == s[i])) { i++; j++ } else if (j < p.length && p[j] == '*') { star = j++; match = i } else if (star != -1) { j = star + 1; i = ++match } else return \"NO_MATCH\" }; while (j < p.length && p[j] == '*') j++; return if (j == p.length) \"MATCH\" else \"NO_MATCH\" }"),
        q("ST-30", "Minimum Additions to Make Parentheses Valid", "Given a parentheses string S of '(' and ')', compute the minimum number of parentheses we must insert so that the resulting string is valid.", "Strings", "Balance Deficit Tracking", "Hard", "())", "1", "(((", "3", "1 <= |S| <= 10^5", "Parentheses string S.", "Minimum insertions needed.", "strings,greedy,parentheses", "O(N)", "O(1)", "minAddToMakeValid", "s: String", "String", "fun minAddToMakeValid(s: String): String { var open = 0; var add = 0; for (c in s) if (c == '(') open++ else if (open > 0) open-- else add++; return (open + add).toString() }")
    )
}
